/* Catalogo delle regole del coach: GENERATO da tools/genera-catalogo.js a partire da
   docs/coach-mappa-regole.md (npm run catalogo). Non si modifica a mano.
   Ogni regola: codice, area, descrizione. Per spegnere una regola vedi regolaAttiva() in parametri.js. */
const COACH_REGOLE = [
  {"codice":"SUG-01","area":"Aiuto alla scelta manuale degli esercizi","testo":"multiarticolare a inizio seduta: <2 esercizi gia in scheda +40 (\"multiarticolare da fare a inizio seduta\"); <2 multiarticolari +25 (\"serve ancora un multiarticolare\"); altrimenti +8"},
  {"codice":"SUG-02","area":"Aiuto alla scelta manuale degli esercizi","testo":"isolamento: se ci sono gia >=3 esercizi +30 (\"isolamento adatto alla seconda parte\"), altrimenti -15"},
  {"codice":"SUG-03","area":"Aiuto alla scelta manuale degli esercizi","testo":"saturazione gruppo: >=3 esercizi dello stesso gruppo -45 (\"gruppo gia molto allenato oggi\"); ==2 -12"},
  {"codice":"SUG-04","area":"Aiuto alla scelta manuale degli esercizi","testo":"continuita: stesso gruppo di partenza (se <3) +28; antagonista +22; sinergico +16 (mappa MUSCLE_GROUPS: petto<->schiena, spalle->schiena, ecc.)"},
  {"codice":"SUG-05","area":"Aiuto alla scelta manuale degli esercizi","testo":"core: >=4 esercizi gia in scheda +26 (\"ottimo per chiudere la seduta\"), altrimenti -30"},
  {"codice":"SUG-06","area":"Aiuto alla scelta manuale degli esercizi","testo":"non due multiarticolari uguali di fila sullo stesso gruppo: -8"},
  {"codice":"SUG-07","area":"Aiuto alla scelta manuale degli esercizi","testo":"gia previsto in un altro giorno della settimana: -20 per giorno (\"gia previsto in un altro giorno\")"},
  {"codice":"SUG-08","area":"Aiuto alla scelta manuale degli esercizi","testo":"diversita: al massimo 2 proposte per gruppo"},
  {"codice":"PRG-01","area":"Costruzione del programma","testo":"durata e blocchi per livello (strutturaProgramma): principiante 8 sett. (blocco 4 = 3+1 scarico); intermedio 12 sett. (blocco 4); avanzato 12 sett. (blocco 6 = 5+1). Fasi: ogni ultima settimana del blocco = 'scarico'."},
  {"codice":"PRG-02","area":"Costruzione del programma","testo":"divisione settimanale (splitFor / splitPerFrequenza): <=2 giorni Full Body; principiante 3 gg Full Body 3x, 4+ Upper/Lower; intermedio e avanzato 3 Upper/Lower/Full Body (ABB-05; il PPL una volta sola resta per chi sceglie la frequenza 1), 4 Upper/Lower x2, 5 PPL+UL, 6 PPL x2; avanzato (stessi schemi per 3-6 gg). Se l'utente sceglie la frequenza (1x, 2x, 3x a settimana per muscolo) si rispetta (Schoenfeld 2019, Ramos-Campo 2024): 1x -> PPL/Upper-Lower + \"punti deboli\"; 2x -> Upper/Lower/FullBody...; 3x -> Full Body ecc."},
  {"codice":"PRG-03","area":"Costruzione del programma","testo":"numero di esercizi per seduta (exerciseCountFor): n = floor((minuti - 10) / (serie*(35+recupero multiarticolare)/60)), min 3, max 7. Principiante con poca fiducia (psico) e >3 esercizi: -1."},
  {"codice":"PRG-04","area":"Costruzione del programma","testo":"mescola fino a 3 obiettivi (schemaMisto): il primo decide lo schema; forza come secondario -> il primo multiarticolare diventa 5x5 pesante; massa secondario -> isolamenti 3x12; ricomposizione o salute secondari -> tetto 4 serie; dimagrimento -> nota cardio."},
  {"codice":"PRG-05","area":"Costruzione del programma","testo":"ogni giorno e una \"ricetta\": lista di posti (spinta orizzontale, tirata verticale, hinge, squat, isolamenti...). Ricette: push, pull (2 varianti), legs, upper (2 varianti), lower (2 varianti), fullbody (3 varianti), punti deboli (dalle priorita dell'utente)."},
  {"codice":"PRG-06","area":"Costruzione del programma","testo":"per ogni posto: candidati = esercizi della libreria che rispondono alla definizione del posto (SLOT_DEF: 17 definizioni); punteggio = classifica degli esperti (PRIORI, ~60 esercizi, 1.5-3) + bonus +3 per il bilanciere pesante al primo posto (non se cauto, -3 se cauto) + bonus biomeccanico (bonusBiomecc) + gradito +3 + in allungamento +1.5 - gia usato in settimana (-1 principiante, -4 altri) + variazione casuale controllata da un seme (0-1 principiante, 0-2.5 altri, moltiplicata per il fattore varieta psicologico) - 2 al bilanciere se \"a disagio\"."},
  {"codice":"PRG-07","area":"Costruzione del programma","testo":"vincoli: attrezzi della palestra, luogo (casa con manubri / corpo libero), esercizi odiati, fastidi (RISCHIO: spalle, ginocchia, schiena) tramite consentito(); al massimo 1 esercizio pesante per la schiena a seduta (SCHIENA_PESANTE)."},
  {"codice":"PRG-08","area":"Costruzione del programma","testo":"con obiettivo forza il primo esercizio pesante e FISSO (niente variazione): la forza e specifica dello strumento."},
  {"codice":"PRG-09","area":"Costruzione del programma","testo":"se l'esercizio migliore non e consentito si registra la sostituzione (\"Evito X: uso Y\")."},
  {"codice":"PRG-10","area":"Costruzione del programma","testo":"allungamento (SCAMBI_ALLUNGAMENTO): dove provato, si scambia la variante (es. pushdown -> estensione sopra la testa, leg curl sdraiato -> seduto, French press -> sopra la testa) se consentita (Maeo 2021-2023)."},
  {"codice":"PRG-11","area":"Costruzione del programma","testo":"PHUL: l'intermedio (senza metodo famoso) con upper/lower: la prima seduta e \"forza\", la seconda \"ipertrofia\". Con 3 giorni (Upper / Lower / Full Body) upper e lower sono \"forza\" e il full body e \"ipertrofia\": ogni muscolo prova carichi alti e carichi medi."},
  {"codice":"PRG-12","area":"Costruzione del programma","testo":"tipo di carico (tipoCarico): isolamento (non multiarticolare), macchina (multiarticolare non nell'elenco), pesante (BIL_PESANTI: squat, front squat, stacchi, panche col bilanciere, military, rematore col bilanciere, T-bar, good morning)."},
  {"codice":"PRG-13","area":"Costruzione del programma","testo":"ripetizioni: pesante 5 se forza, altrimenti max 8; macchina 8+ (8 se forza; con obiettivo forza max 4 serie); isolamento 10+ (con forza max 3 serie). Recupero: pesante = recupero multi dell'obiettivo; macchina = max(90, 75%); isolamento = max(60, recupero iso)."},
  {"codice":"PRG-14","area":"Costruzione del programma","testo":"primo multiarticolare con forza come secondo obiettivo: 5x5 con 180 s (non sopra i 65 anni)."},
  {"codice":"PRG-15","area":"Costruzione del programma","testo":"forza come primo obiettivo, non principiante, esercizio pesante, non cauto: 6x3 con 180 s."},
  {"codice":"PRG-16","area":"Costruzione del programma","testo":"giorno 'forza' (PHUL): pesante 4 serie, recupero >=180; giorno 'ipertrofia': pesante 8 rip, altri multi 10, isolamenti 12."},
  {"codice":"PRG-17","area":"Costruzione del programma","testo":"massa come secondario: isolamenti 3x12. Tetto serie dell'obiettivo (4 con ricomposizione/salute)."},
  {"codice":"PRG-18","area":"Costruzione del programma","testo":"principiante: max 3 serie (2-3 serie impegnative, Barbell Medicine)."},
  {"codice":"PRG-19","area":"Costruzione del programma","testo":"over 65: max 3 serie, 8-12 rip. PAR-Q positivo: multiarticolari 8-12 rip (60-80% del carico, niente apnea; ACSM). \"cauto\" = over 65 oppure PAR-Q positivo: niente pesanti favoriti."},
  {"codice":"PRG-20","area":"Costruzione del programma","testo":"donne: recupero -15% (min 60 s) (PeerJ 2025). A tempo (plank ecc.): ripetizioni = valore della libreria (secondi). Recupero arrotondato a 15 s."},
  {"codice":"PRG-21","area":"Costruzione del programma","testo":"schemi di movimento mancanti (piramide di Helms): ogni settimana servono i 6 schemi (squat, hinge, spinta/tirata orizzontale, spinta/tirata verticale); se manca, si aggiunge nella seduta piu vuota adatta (3 serie max; cauto/principiante: meno pesanti). Non con i metodi \"essenziale\"."},
  {"codice":"PRG-22","area":"Costruzione del programma","testo":"glutei: se l'obiettivo include glutei, le 4 famiglie ogni settimana (spinta d'anca, squat/affondi, stacchi, abduzioni) 3x12, 75 s."},
  {"codice":"PRG-23","area":"Costruzione del programma","testo":"copertura per regioni (Schoenfeld, Maeo, Pedrosa): se >=3 giorni e obiettivo non salute: femorali con flessione di ginocchio (leg curl) se ci sono gambe; leg extension (retto femorale) per massa o glutei; alzate laterali se c'e panca e obiettivo massa/ricomposizione; bicipite: se >=2 curl senza Scott/spider, un curl diventa Scott/Spider (Pedrosa 2025). Aggiunte da 2 serie, 75 s."},
  {"codice":"PRG-24","area":"Costruzione del programma","testo":"note sui fastidi (SCALE_DOLORE) aggiunte al programma per ogni fastidio dichiarato."},
  {"codice":"PRG-25","area":"Costruzione del programma","testo":"volume settimanale (serie): VOLUME_LIVELLO principiante 8-10, intermedio 10-14, avanzato 14-20; salute 6-12."},
  {"codice":"PRG-26","area":"Costruzione del programma","testo":"fattore fisico: massa magra bassa (FFMI basso) e non dimagrimento: x1,2; massa magra in calo: x0,85."},
  {"codice":"PRG-27","area":"Costruzione del programma","testo":"esigenza del coach (`esigenzaIniziale`, INT-02): +20% di volume all'inizio solo senza bandiere dalla BIA (100% con una, 95% con due), segue l'andamento; =1 se cauto o con un \"momento di vita\" attivo che riduce volume o aumenta RIR; >=1,15 aggiunge la nota \"Coach esigente\". <1 riduce min e max."},
  {"codice":"PRG-28","area":"Costruzione del programma","testo":"conteggio frazionario: 1 serie per il muscolo principale, 0,5 per sinergisti nei multiarticolari (Pelland 2025). Aggiusta le serie (+1 al meno carico, max 5; -1 al piu carico, min 2, senza toccare i \"fissi\") finche il volume e dentro min-max."},
  {"codice":"PRG-29","area":"Costruzione del programma","testo":"priorita: gruppo prioritario x1,2 (x1,5 se avanzato che specializza); avanzato che specializza: gli altri gruppi min 6, max = vMin."},
  {"codice":"PRG-30","area":"Costruzione del programma","testo":"tetto di 11 serie per muscolo per seduta (si tolgono serie dagli esercizi non fissi, min 2)."},
  {"codice":"PRG-31","area":"Costruzione del programma","testo":"principianti e over 65: mai piu di 3 serie per esercizio (ripetuta: gia in PRG-18/19)."},
  {"codice":"PRG-32","area":"Costruzione del programma","testo":"poco sonno (\"male\"): -1 serie sugli accessori (non il primo esercizio, non i \"fissi\"), minimo 2."},
  {"codice":"PRG-33","area":"Costruzione del programma","testo":"la seduta deve stare nei minuti dichiarati (+5 di tolleranza; 8 min di base + serie*(35 s + recupero)): si tolgono serie dagli esercizi non prioritari, prima gli isolamenti; se non basta si toglie l'ultimo isolamento (se restano >3 esercizi)."},
  {"codice":"PRG-34","area":"Costruzione del programma","testo":"tecniche: poco tempo (<=45 min) -> superserie spinta+tirata e drop set sull'ultimo isolamento (non se intensita psicologica bassa); over 65 -> primo multiarticolare \"potenza\"; PAR-Q positivo o over 65 -> \"cluster\" sui pesanti; non principiante e primo esercizio pesante -> avanzato \"back-off\", intermedio \"AMRAP\" (non se intensita bassa); avanzato o intermedio con intensita alta (non poco tempo): tecnica anche su un isolamento."},
  {"codice":"PRG-35","area":"Costruzione del programma","testo":"il metodo scelto (schede famose) decide serie, ripetizioni e pause; il \"tocco\" secondario applica una piccola modifica; alcuni metodi impongono le superserie."},
  {"codice":"PRG-36","area":"Costruzione del programma","testo":"regola del picco e della fine: chi non ama la fatica (intensita bassa) -> -1 serie sull'ultimo esercizio."},
  {"codice":"PRG-37","area":"Costruzione del programma","testo":"note aggiunte al programma: poco tempo (superserie -37% di tempo), over 65 (2-3 serie da 8-12, niente cedimento, 5 minuti di equilibrio), donne (pause piu corte), dimagrimento (10-12 mila passi, +500-1000 a settimana, il cardio non toglie muscolo)."},
  {"codice":"PRG-38","area":"Costruzione del programma","testo":"avanzati: mesociclo con RIR 3,2,1,0 nelle settimane di carico, 4 nello scarico."},
  {"codice":"PRG-39","area":"Costruzione del programma","testo":"esercizi alternativi scelti dall'utente: sostituiti nello stesso posto, peso di partenza dalla libreria."},
  {"codice":"ABB-01","area":"Costruzione del programma","testo":"ordine della seduta (`strOrdina`): prima i multiarticolari (i pesanti col bilanciere davanti alle macchine), poi gli isolamenti dei grandi muscoli, poi quelli dei piccoli (deltoidi, braccia, polpacci), il core sempre in fondo. Il giorno \"punti deboli\" resta nell'ordine di priorita dell'utente. Motivo: ACSM 2009 (grandi prima dei piccoli, multi prima dei mono); per la forza migliora di piu l'esercizio fatto per primo (Nunes 2021); per la massa l'ordine conta poco."},
  {"codice":"ABB-02","area":"Costruzione del programma","testo":"niente esercizi doppi (`strRidondante`): due esercizi con stesso gruppo, stessa parte del muscolo (SOTTOGRUPPI), stesso tipo e stesso schema fanno lo stesso lavoro, e la seconda panca piana diventa una inclinata. Penalita di 4 punti nella scelta del posto. Fanno eccezione lo squat (macchina dopo il bilanciere: 2) e i glutei multiarticolari (2)."},
  {"codice":"ABB-03","area":"Costruzione del programma","testo":"copertura della settimana (`strCopri`): per massa o ricomposizione, non principianti, da 3 giorni: un esercizio per i polpacci se si allenano le gambe, uno per i deltoidi posteriori se ci sono spinte (convenzione dei coach, prove dirette scarse); da 4 giorni anche un curl per il bicipite e un tricipite diretto (studi piccoli: le braccia crescono anche con i soli multiarticolari, l'isolamento sposta la crescita su altre regioni); con 3 giorni o piu e non salute: un esercizio di core a fine seduta (convenzione). Le aggiunte hanno 2-3 serie, `protetto: true` (non si tolgono per il tempo: si tagliano serie agli altri) e fanno crescere la seduta di al massimo due esercizi. Non vale per i metodi \"essenziale\"."},
  {"codice":"ABB-04","area":"Costruzione del programma","testo":"tirate non meno del 90% delle spinte (`strBilancia`): con almeno 8 serie tra spinte e tirate, prima +1 serie alle tirate (al massimo 4, 3 per principianti e over 65), poi -1 alle spinte (minimo 2), infine un esercizio di spinta doppione (lo stesso schema due volte nella stessa seduta: sedute diverse sono la frequenza 2 e non si toccano) diventa una tirata dello stesso tipo di carico (stesso piano se c'e, altrimenti l'altro). Non vale con un metodo famoso. Convenzione dei coach per l'equilibrio delle spalle. Nota alla scheda."},
  {"codice":"ABB-05","area":"Costruzione del programma","testo":"3 giorni per intermedi e avanzati: Upper / Lower / Full Body invece di Push / Pull / Legs (`splitFor`, onboarding.js). Ogni muscolo 2 volte a settimana (ACSM 2026) e nessun muscolo oltre le circa 11 serie frazionarie in una seduta (Pelland, preprint 2025). Chi sceglie la frequenza 1 tiene il Push / Pull / Legs."},
  {"codice":"ABB-06","area":"Costruzione del programma","testo":"superserie sicure (`strSuperserie`): solo antagonisti (spinta-tirata, petto-schiena, bicipiti-tricipiti, quadricipiti-femorali), adiacenti, mai con un fondamentale pesante, a tempo o di core; gli esercizi si avvicinano nell'ordine senza uscire dal loro gruppo (multiarticolari con multiarticolari, isolamenti con isolamenti). Antagonisti: stesso volume e crescita in circa un terzo di tempo in meno (meta-analisi 2025, 19 studi); coppie dello stesso muscolo: meno volume. Si usano con poco tempo (<=45 minuti), con il \"tocco\" superserie e con i metodi \"superserie\" (tranne la Recommended Routine, che ha le sue coppie)."},
  {"codice":"ABB-07","area":"Costruzione del programma","testo":"schiena pesante due giorni di fila: se il giorno prima c'era un esercizio di `SCHIENA_PESANTE` o lo stacco rumeno, la scelta dei posti penalizza di 5 punti gli stessi esercizi (convenzione). Non vale con un metodo."},
  {"codice":"ABB-08","area":"Costruzione del programma","testo":"il fondamentale (primo multiarticolare pesante) non ha meno serie degli altri multiarticolari non pesanti della seduta (un secondo fondamentale pesante, come nella forza, ha le sue) (`strFinale`, dopo il taglio del tempo): le serie si spostano (+1 al fondamentale, -1 all'altro, minimo 2), non si aggiungono. Non vale per i \"fissi\" ne per gli stacchi (ABB-09)."},
  {"codice":"ABB-09","area":"Costruzione del programma","testo":"gli stacchi da terra (stacco da terra, sumo, trap bar, good morning) al massimo 3 serie: molta fatica sistemica per lo stimolo che danno (Israetel, Helms: convenzione)."},
  {"codice":"ABB-10","area":"Costruzione del programma","testo":"priorita: a parita di tipo, il gruppo prioritario dell'utente per primo (principio della priorita di Arnold; le prestazioni migliorano di piu negli esercizi fatti all'inizio, Nunes 2021)."},
  {"codice":"MET-01","area":"Metodi famosi e scelta della struttura","testo":"catalogo di 25 metodi (8 non applicabili: solo ispirazione). Tabella estratta dal codice:"},
  {"codice":"MET-02","area":"Metodi famosi e scelta della struttura","testo":"punteggio di un metodo per te (metodiPerTe): luogo non adatto = escluso; livello adatto +3 (altrimenti -4); giorni adatti +2 (altrimenti -1); obiettivo principale adatto +2 (altrimenti -2); minuti disponibili: sotto il minimo del metodo -2, dentro il range (+15) +1; intensita uguale a quella psicologica +2 (se intensita bassa e metodo alto: -4); routine (varieta 0) con metodo rigido +2; chi ama cambiare (varieta>1): +2 con metodi variabili, -1 con quelli senza variazione; fiducia bassa: +2 per metodi flessibili da <=45 minuti, -2 per intensita alta; disagio in palestra: +2 a corpo libero/dose minima, -2 ai metodi con fondamentali pesanti; motivazione \"piacere\": +1 ai metodi con record/AMRAP; tutto-o-niente: +2 se sedute <=30 min; corpo libero: +3 alla Recommended Routine; \"momento di vita\": Mantenimento +6/+8 se volume <=0,6/0,5, Dose minima +4, -3 ai metodi ad alta intensita se il volume e ridotto, +1 ai rigidi per chi ha ansia; il metodo del coach +1; non applicabili -1."},
  {"codice":"MET-03","area":"Metodi famosi e scelta della struttura","testo":"fattore fisico sulla scelta (sceltaMetodo): massa magra bassa +2 a GBR, Hatfield, Reddit PPL, PHUL; grasso alto +1 a coach/minimo/GBR e -1 ai metodi con pesanti; massa magra in calo -2 ai metodi ad alta intensita."},
  {"codice":"MET-04","area":"Metodi famosi e scelta della struttura","testo":"ammissione (metodoAmmesso): applicabile, livello, giorni, luogo, obiettivo, cauto (PAR-Q o over 65) esclude alta intensita; Recommended Routine solo a corpo libero; Mantenimento solo con un periodo di vita a volume <=0,6; Dose minima solo con periodo difficile, <=35 minuti, fiducia bassa o tutto-o-niente; HIT solo con intensita psicologica alta; minuti disponibili almeno il minimo-5."},
  {"codice":"MET-05","area":"Metodi famosi e scelta della struttura","testo":"la STRUTTURA cambia solo se un metodo batte chiaramente quello del coach (+2 punti); un secondo metodo (fino a -3 punti dal coach) puo dare un \"tocco\": AMRAP sull'ultima serie del primo fondamentale, ultimo isolamento da 15-20 (piramide), isolamenti da 12-15, superserie spinte+tirate."},
  {"codice":"MET-06","area":"Metodi famosi e scelta della struttura","testo":"cosa decide un metodo applicato: split, numero di esercizi, ricette dei posti, schema (serie, ripetizioni, recuperi, tecniche), superserie, PHUL, luogo. Il programma mostra \"da dove ha preso spunto\" con i motivi (fino a 3)."},
  {"codice":"EPO-01","area":"Metodi famosi e scelta della struttura","testo":"Golden Six (`goldensix`, Reg Park e Arnold): 3 giorni, full body, 6 posti (squat, spinta orizzontale, tirata verticale, spinta verticale, curl, core), serie e ripetizioni 4x10, 3x10, 3x8, 4x10, 3x10, 3x15, pause 120 s sullo squat e 90 s sul resto (60 sul core); il press dietro la nuca e il press normale. Stessa seduta ogni volta (EPO-07). Nessuna aggiunta del coach (`essenziale`)."},
  {"codice":"EPO-02","area":"Metodi famosi e scelta della struttura","testo":"5x5 di Reg Park (`park`, intermedi): full body A/B, 3 giorni. A: squat, tirata verticale, spinta orizzontale 5x5 e polpacci 2x15; B: squat, tirata orizzontale, spinta verticale 5x5, stacco 3x5 e polpacci. Pause 180 s. Fondamentali pesanti favoriti (`pesanti`)."},
  {"codice":"EPO-03","area":"Metodi famosi e scelta della struttura","testo":"Arnold a 6 giorni (`arnold6`, avanzati, 6 giorni): Petto e Schiena / Spalle e Braccia / Gambe, due volte; 4 serie sui fondamentali dei primi quattro posti e 3 sul resto (l'originale ne ha di piu: il coach toglie una serie), 90 s, tecnica \"piramide\" sui multiarticolari, petto e schiena in superserie (spinta + tirata). Due sedute nuove nelle ricette: `petto-schiena` e `spalle-braccia`."},
  {"codice":"EPO-04","area":"Metodi famosi e scelta della struttura","testo":"Gironda 8x8 (`gironda`, intermedi e avanzati, 3 giorni Push / Pull / Legs): un multiarticolare per seduta in 8 serie da 8 con 30 s di pausa e il 70% del carico (`fattoreCarico` 0,7, applicato dopo la stima dai dati del corpo), poi 3 esercizi da 3x12 a 75 s. Mai bilancieri pesanti (`leggeri`): sotto i 60 s di pausa il volume cala e la crescita ne risente un poco (Singer 2024). Tecnica \"ottoperotto\"."},
  {"codice":"EPO-05","area":"Metodi famosi e scelta della struttura","testo":"Heavy Duty di Mentzer (metodo `hit`, rivisto): 2 serie (non una: Krieger 2010) al cedimento, 8 ripetizioni per la parte alta e 15 per gambe e glutei (Mentzer: 6-10 e 12-20), pausa 120 s; con 3 giorni split Petto e Schiena / Gambe / Spalle e Braccia, cosi ogni muscolo riposa 7 giorni (Mentzer: 4-7); l'ultimo esercizio non pesante ha \"riposo-pausa\" (Prestes 2019: stessa crescita, meno tempo). Il fondamentale resta per primo: il pre-affaticamento non da piu crescita (Gentil e altri). Senza aggiunte del coach (`essenziale`). Con un metodo non si applicano le superserie e il drop set del poco tempo."},
  {"codice":"EPO-06","area":"Metodi famosi e scelta della struttura","testo":"Reeves e Yates: solo ispirazione (`applicabile: false`) e sedute pronte. Reeves parte dai muscoli piccoli (contro ABB-01); Yates porta tutto al cedimento (le fonti sulle sue serie divergono: 2 di lavoro nel 1987-92, una dopo)."},
  {"codice":"EPO-07","area":"Metodi famosi e scelta della struttura","testo":"`ripeti`: i metodi con la stessa seduta ogni volta (Golden Six, Park, Arnold, Gironda) non penalizzano l'esercizio gia usato in settimana (-4): ogni giorno uguale ha gli stessi esercizi."},
  {"codice":"TEC-01","area":"Metodi famosi e scelta della struttura","testo":"piramide: carico che sale, ripetizioni che scendono (12, 10, 8, 6). Assegnata da `arnold6`; le sedute pronte di Arnold la portano. Non e tra le tecniche al cedimento."},
  {"codice":"TEC-02","area":"Metodi famosi e scelta della struttura","testo":"negative: l'ultima serie scende in 4-5 secondi con un compagno che aiuta a salire. Il sovraccarico eccentrico da un piccolo vantaggio sulla massa (Schoenfeld 2017; ACSM 2026). Solo testo: nessun metodo la assegna da solo."},
  {"codice":"TEC-03","area":"Metodi famosi e scelta della struttura","testo":"ripetizioni forzate: un compagno aiuta per 1-2 ripetizioni oltre il cedimento, su panca o macchine. Solo testo."},
  {"codice":"TEC-04","area":"Metodi famosi e scelta della struttura","testo":"riposo-pausa: al cedimento 15 secondi e ancora qualche ripetizione, due volte. Assegnata al `hit` sull'ultimo esercizio non pesante e di non-core; le sedute di Mentzer la portano."},
  {"codice":"TEC-05","area":"Metodi famosi e scelta della struttura","testo":"contrazione di picco: 2 secondi di stretta in cima a ogni ripetizione. Solo testo."},
  {"codice":"TEC-06","area":"Metodi famosi e scelta della struttura","testo":"Gironda 8x8 (`ottoperotto`): 8 serie da 8, 30 secondi, circa il 70% del carico delle 8 ripetizioni."},
  {"codice":"TEC-07","area":"Metodi famosi e scelta della struttura","testo":"le tecniche al cedimento (negative, forzate, riposo-pausa, oltre a drop, AMRAP, parziali e calibrazione) contano per il tetto di RIC-04: al massimo una per seduta, nessuna in scarico o con prontezza sotto 50."},
  {"codice":"PRZ-01","area":"Prontezza prima della seduta","testo":"punteggio = media pesata: sonno 30, stress 25, dolenzia 25, voglia 20 (FitnessVolt, Hooper); voce facoltativa \"ciclo\" peso 15 (trattata come sonno e stress: niente programmazione per fasi, Colenso-Semple 2023). Ogni risposta vale 0, 1 o 2 su 2."},
  {"codice":"PRZ-02","area":"Prontezza prima della seduta","testo":"fattore sul carico dei multiarticolari non ancora iniziati: >=70% come da piano; 50-69% x0,96 (\"un RIR in piu\", -4%); <50% x0,9 (\"seduta leggera\", -10%). Gli isolamenti non si toccano (il sonno scarso cala la forza solo nei multiarticolari, Knowles 2018)."},
  {"codice":"PRZ-03","area":"Prontezza prima della seduta","testo":"giornata ottima (>=70%) in settimana di carico: +1 serie sugli isolamenti (max 5 serie)."},
  {"codice":"PRZ-04","area":"Prontezza prima della seduta","testo":"stanchezza persistente: 3 giorni consecutivi negli ultimi 7 sotto il 50% -> scarico anticipato per 2 sedute (Hooper), se non c'e gia."},
  {"codice":"PRZ-05","area":"Prontezza prima della seduta","testo":"\"Mi sento male\" (Harvard Health): ferma tutto, dice cosa fare e chiude la seduta come interrotta; una seduta interrotta non conta per i carichi."},
  {"codice":"PRO-01","area":"Il carico della prossima seduta","testo":"incremento (incrementoPer): gambe/glutei multiarticolare +5 kg, isolamento +2,5 kg; resto multiarticolare +2,5 kg, isolamento +1 kg. Arrotondamento a 0,5 kg."},
  {"codice":"PRO-02","area":"Il carico della prossima seduta","testo":"esito di una seduta per esercizio (esito): 'saltato' se nessuna serie fatta; 'ok' se tutte le serie fatte con almeno le ripetizioni previste; altrimenti 'mancato'."},
  {"codice":"PRO-03","area":"Il carico della prossima seduta","testo":"(da commento) stesso carico finche tutte le serie arrivano alle ripetizioni; poi aumento; mancato una volta = stesso carico e si punta a piu ripetizioni; mancato due volte di fila = -10% (il principiante -5%, vedi sotto); scarico = serie -40% e carico -10%. (la logica effettiva e in caricoProssimo, sezione E)"},
  {"codice":"PRO-04","area":"Il carico della prossima seduta","testo":"freno della BIA (frenoBia): se la massa magra e scesa di almeno 1 kg tra le ultime due misure, niente aumenti (\"per ora tengo fermi i carichi e punto al recupero\")."},
  {"codice":"CAR-01","area":"Il carico della prossima seduta","testo":"esercizi a tempo (plank ecc.): tenuta completata = +5 secondi; altrimenti stessa durata."},
  {"codice":"CAR-02","area":"Il carico della prossima seduta","testo":"mai fatto: carico del programma, che dal 1 ottobre e una stima dai dati del corpo (vedi PAR); in scarico x0,9."},
  {"codice":"CAR-03","area":"Il carico della prossima seduta","testo":"settimana di scarico del programma: serie = serie base x dose, carico = ultimo x dose; la dose dipende dalla fatica (livelloFatica, Bell 2024): bassa (RPE medio <7 e prontezza >=70) volume -35% (carico x0,95); media volume -50% e carico -10%; alta (RPE >=9 o prontezza <50) volume -70% e carico -10%. \"Mai stop totale: la forza calerebbe\"."},
  {"codice":"CAR-04","area":"Il carico della prossima seduta","testo":"rientro dopo una pausa su QUELL'esercizio (detraining, SBS): 10-20 giorni -10%; 21-28 giorni -20%; fino a 90 giorni -30%; oltre -50%; sopra i 65 anni i giorni contano il doppio. Con \"3 ripetizioni in riserva\"."},
  {"codice":"CAR-05","area":"Il carico della prossima seduta","testo":"corpo libero (carico 0): tutte le serie complete = +1 ripetizione; altrimenti stesse ripetizioni."},
  {"codice":"CAR-06","area":"Il carico della prossima seduta","testo":"tutte le serie complete (\"ok\"):"},
  {"codice":"CAR-07","area":"Il carico della prossima seduta","testo":"due volte di fila \"mancato\": principiante su un pesante gia in stallo una volta -> stesso peso, schema 5x3 (poi 6x2 e 10x1, GZCLP); principiante -5%; tutti gli altri -10% (\"si ricostruisce\"). Contatore stalli per esercizio."},
  {"codice":"CAR-08","area":"Il carico della prossima seduta","testo":"scarico mirato: massimale stimato in calo per due sedute di fila (3 punti) -> -10% e meta serie solo su quell'esercizio (Dr. Muscle)."},
  {"codice":"CAR-09","area":"Il carico della prossima seduta","testo":"un solo \"mancato\": principiante stesso peso con +30 s di pausa; altri stesso carico, \"punta a piu ripetizioni\"."},
  {"codice":"CAR-10","area":"Il carico della prossima seduta","testo":"scarico deciso dal coach attivo (aggiusti.scarico): carico x0,9 e serie = 60% della base (min 2)."},
  {"codice":"CAR-11","area":"Il carico della prossima seduta","testo":"aggiusto per esercizio: fattore (dolore, reset) -> carico x fattore; \"blocca\" -> toglie l'aumento; \"extra\" -> +1 incremento in piu; \"alte ripetizioni\" (gomito/ginocchio) -> almeno 12 ripetizioni."},
  {"codice":"CAR-12","area":"Il carico della prossima seduta","testo":"a ogni esercizio con carico si aggiunge il bersaglio di ripetizioni in riserva (testoRir)."},
  {"codice":"CAR-13","area":"Il carico della prossima seduta","testo":"tecnica \"back-off\": dopo la prima serie le altre a -95%."},
  {"codice":"CAR-14","area":"Il carico della prossima seduta","testo":"calibrazione del RIR: nell'ultima settimana di carico di ogni blocco, l'ultima serie del primo isolamento va a cedimento; il coach confronta il RIR stimato (10 - RPE medio delle altre serie) con quello vero e aggiorna una correzione (rirBias, media mobile 50%, limitata a -2..+3)."},
  {"codice":"CAR-15","area":"Il carico della prossima seduta","testo":"dopo la seduta (imparaDallaSeduta): conta gli stalli e aggiorna la correzione."},
  {"codice":"PAR-01","area":"Il carico della prossima seduta","testo":"dati del corpo (`contestoCarichi`): si usano i dati appena inseriti, altrimenti l'ultima BIA salvata. Ordine di preferenza: massa muscolare scheletrica (SMM, riferimento 34 kg) > massa magra (FFM, riferimento 61,5 kg) > peso x massa grassa % > solo peso (x0,82 uomini, x0,74 donne). Valori fuori scala vengono ignorati."},
  {"codice":"PAR-02","area":"Il carico della prossima seduta","testo":"fattore dal corpo (`scalaDaCorpo`) = massa / riferimento x livello (principiante 1, intermedio 1,3, avanzato 1,6) x sesso (donne, solo parte alta del corpo: 0,9; gambe e glutei no) x eta (50-64 anni 0,95; da 65 anni 0,85) x PAR-Q positivo 0,85 x prudenza 0,85 (si parte sotto il limite). Limiti 0,45-1,8."},
  {"codice":"PAR-03","area":"Il carico della prossima seduta","testo":"dallo storico (`scalaDaStorico`): mediana, sugli esercizi gia fatti, del rapporto tra il massimale stimato (Epley) e quello del valore di libreria. Il peso dello storico cresce con il numero di esercizi fatti: a 4 esercizi la stima si fonda solo sulle sedute e la BIA non conta piu."},
  {"codice":"PAR-04","area":"Il carico della prossima seduta","testo":"peso finale = valore di libreria x fattore, arrotondato a pesi reali: barra da 20 kg (mai sotto, salvo esercizi con default inferiore), manubri e corpo libero a passi di 1 kg (2 kg da 10 kg), macchine e cavi a 2,5 kg. Esercizi a corpo libero o a tempo: nessuna stima."},
  {"codice":"PAR-05","area":"Il carico della prossima seduta","testo":"dove si applica: creazione del programma (tutte le sedute, comprese le aggiunte per schemi mancanti, regioni e glutei), esercizi nuovi o sostituiti dal coach (dolore, azione \"cambia variante\", rotazione accessori), \"Macchinario occupato\", seduta libera e aggiunta dalla libreria. Senza consenso ai dati o senza dati del corpo resta il valore di libreria. Il record porta il segno `stimato` e la nota col motivo, che compare alla prima seduta (\"Carico di partenza stimato dalla tua massa muscolare...\")."},
  {"codice":"CAR-16","area":"Il carico della prossima seduta","testo":"calibrazione, serie facili: nelle prime sedute con un esercizio (meno di 3 in storico) l'autoregolazione dall'RPE sale piu in fretta: +5% per punto di scarto dal bersaglio (massimo +15%) invece di +4% (massimo +10%)."},
  {"codice":"CAR-17","area":"Il carico della prossima seduta","testo":"calibrazione, carico troppo alto: nelle prime sedute, se le serie sono molto sotto il previsto (meno del 60% completate, oppure ripetizioni medie di almeno 3 sotto il bersaglio) il carico scende subito del 5% senza aspettare il secondo errore. Un errore piccolo non cambia il carico."},
  {"codice":"BIO-01","area":"Biomeccanica e prove fai-da-te","testo":"suggerimenti esterni (cueEsercizio): per ogni schema di movimento una frase (squat \"spingi via il pavimento con tutto il piede\"; hinge \"fianchi indietro come per chiudere una porta\"; spinta orizzontale \"allontana il peso da te\"; spinta verticale \"verso il soffitto e passa con la testa sotto\"; tirata orizzontale \"gomiti verso i fianchi\"; tirata verticale \"gomiti verso le tasche\"); per gli isolamenti \"senti il muscolo che lavora: discesa in 2-3 secondi\"; per tutti \"stessa ampiezza a ogni seduta\". Se nelle prove la larghezza dello squat e stata scelta: la ricorda; se la caviglia e rigida: \"talloni su due dischi sottili\"."},
  {"codice":"BIO-02","area":"Biomeccanica e prove fai-da-te","testo":"respirazione (respiroPer): con PAR-Q positivo \"non trattenere il fiato, 8-12 ripetizioni, carichi moderati\"."},
  {"codice":"BIO-03","area":"Biomeccanica e prove fai-da-te","testo":"cedimento solo su varianti stabili (stabile): isolamenti e macchine; i pesi liberi multiarticolari restano ad almeno 1 RIR."},
  {"codice":"BIO-04","area":"Biomeccanica e prove fai-da-te","testo":"prove fai-da-te (TEST_FAI_DA_TE, Horschig/Movement Fix): caviglia (ginocchio al muro a 12 cm), spalle (braccia al muro), larghezza dello squat. DAL 01/10 le istruzioni sono esplicite (passi, risultato, sicurezza, a cosa serve)."},
  {"codice":"BIO-05","area":"Biomeccanica e prove fai-da-te","testo":"bonus nella scelta degli esercizi (bonusBiomecc): caviglia rigida -> squat guidati (hack, leg press, pendulum, goblet, multipower) +2, squat/front squat col bilanciere -2; spalle \"no\" o fastidio alle spalle -> landmine press +3, military/lento avanti/Arnold -3; fastidio alle spalle sulle spinte orizzontali: manubri, chest press, presa stretta +1,5; croci ai cavi +0,5 (tensione su tutto il movimento, Menno); calf raise in piedi +1 (gastrocnemio cresce il doppio, Kinoshita 2023)."},
  {"codice":"BIO-06","area":"Biomeccanica e prove fai-da-te","testo":"scale di modifica per zona (SCALE_DOLORE, Lehman): spalle (spinte con presa stretta o manubri a presa neutra), ginocchia (leg extension isometrica 5x45 s, dolore max 3/10, discesa 3-4 s), schiena bassa (riscaldamento McGill: curl-up, plank laterale, bird dog; tenute 8-6-4 s). Si aggiungono come note al programma."},
  {"codice":"BIO-07","area":"Biomeccanica e prove fai-da-te","testo":"copertura per regioni: vedi PRG-23."},
  {"codice":"DEC-01","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"dolore fino a 3/10: si continua e si osserva (\"se domattina e peggio, segnalalo\") — Silbernagel 2007."},
  {"codice":"DEC-02","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"dolore 4-5/10: carico -10% sugli esercizi coinvolti per 2 sedute (zone gomito/ginocchio: segnale \"alte ripetizioni\"); la mattina dopo il coach chiede se e tornato normale (vedi controllo dolore)."},
  {"codice":"DEC-03","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"dolore >=6/10, oppure tornato nella stessa zona (>=4/10) nelle ultime 2 sedute: l'esercizio si SOSTITUISCE con una variante che carica meno l'articolazione (tabella SOSTITUZIONI), se esiste; altrimenti carico -20% per 2 sedute. Con >=6/10 anche l'avviso \"fatti vedere da un medico o fisioterapista\"."},
  {"codice":"DEC-04","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"dolore che cresce per tre sedute di fila nella stessa zona: \"fatti vedere da un fisioterapista\"."},
  {"codice":"DEC-05","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"seduta \"pesante\" = RPE di sessione >=9 oppure arrivato stanco. 3 sedute su 4 pesanti (con almeno 3 feedback precedenti): propone di togliere un allenamento a settimana (Bell 2022)."},
  {"codice":"DEC-06","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"almeno 2 sedute su 3 pesanti: la prossima seduta e di SCARICO (serie -40%, carico -10%)."},
  {"codice":"DEC-07","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"altrimenti: carichi \"pesanti\" e RPE >=9 -> nessun aumento la prossima volta; carichi \"leggeri\" e RPE <=5 senza dolore -> un aumento extra dove hai completato tutte le serie."},
  {"codice":"DEC-08","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"nessuna regola scattata: \"Seduta nella norma: il programma prosegue come previsto.\""},
  {"codice":"DEC-09","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"applicazione (applicaDecisioni): scrive gli \"aggiusti\" per esercizio (fattore, sedute, motivo), lo scarico, e per la sostituzione cambia il nome in TUTTI i giorni del piano (peso della libreria, serie non fatte, nota \"Variante scelta dal coach\"). Tutto annullabile (ripristina dati, aggiusti, giorni di riposo)."},
  {"codice":"DEC-10","area":"Dopo la seduta: questionario, decisioni, dolore","testo":"riduciFrequenza: se i giorni di allenamento sono piu di 2, il giorno con meno serie diventa riposo (annullabile); se sono 2 o meno: \"meglio ridurre le serie che i giorni\"."},
  {"codice":"LIV-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"livello stimato dai numeri (livelloStimato; serve almeno 6 sedute): mesi regolari = settimane con >=2 sedute / 4,33; frequenza = sedute / settimane attive; difficolta = media per seduta di (+0,5 se c'e un esercizio \"pesante\", +0,2 se ci sono tecniche/extra, +0,3 se >=5 esercizi). Principiante <6 mesi regolari; intermedio >=6 mesi e >=2 sedute/sett.; avanzato >=24 mesi, >=3 sedute/sett., difficolta >=0,5 (NSCA, Helms). Se il livello stimato e piu alto di quello del profilo, propone \"Aggiorna il livello\"."},
  {"codice":"LIV-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"livello \"verificato sui numeri\" (squat, stacco, panca, military come multipli del peso corporeo): non applicato. Le tabelle STANDARD_FORZA e ALZATE_BASE non erano lette da nessuna funzione (`livelloStimato` non le usa) e sono state tolte il 2026-10-05: per attivarla vanno riscritte."},
  {"codice":"STA-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"esercizio fermo (eserciziFermi): servono >=3 sedute con massimale stimato (e1RM). Soglia per livello: principiante 2 sedute (finestra: ultime 3), intermedio 4 settimane, avanzato 8 settimane. E' fermo se l'ultimo e1RM <= quello piu vecchio della finestra e <= il migliore precedente."},
  {"codice":"STA-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"azioni sul fermo (max 3 esercizi): se recuperi bene (media degli ultimi 5 punteggi di prontezza >=60, o nessun dato) \"+20% serie\", altrimenti \"-20% serie\"; sempre \"Cambia variante\"; per i pesanti anche \"Reset -10%\" (si ricostruisce, stile 5/3/1). Serie nel piano limitate a 2-6."},
  {"codice":"STA-03","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"rotazione accessori: all'inizio di ogni blocco (settimana 1 + k*blocco), se non gia fatta in quel blocco e l'obiettivo non e forza: propone di ruotare gli isolamenti (non i fondamentali) con equivalenti."},
  {"codice":"STR-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"strain (Foster): carico settimanale = somma(RPE di sessione x minuti); monotonia = media giornaliera / deviazione standard; strain = carico x monotonia. Se lo strain sale per due settimane di fila e la fatica media >=8 e non c'e gia uno scarico: propone due sedute di scarico."},
  {"codice":"SCH-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"controllo schemi nel piano: manca uno dei 6 schemi di movimento; squilibri: spinte orizzontali senza tirate orizzontali, spinte verticali senza tirate verticali."},
  {"codice":"COR-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"in deficit calorico: calo di peso a settimana (da due misure BIA/peso) < -1% = troppo in fretta (rischio perdere muscolo); da -0,5% a -1% = ritmo ideale; altrimenti \"scende poco\"."},
  {"codice":"COR-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"ricomposizione: realistica se principiante o massa grassa alta (>32% donne, >25% uomini); altrimenti meglio fasi separate."},
  {"codice":"COR-03","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"proteine: con massa magra nota 2,35-2,75 g per kg di massa magra; altrimenti 2 g/kg di peso (1,75 per le donne). Passi: deficit 10-12 mila (+500-1000 a settimana), altrimenti 6-8 mila. Obiettivo salute: minuti di pesi della settimana (30-60 min bastano) + 150-300 min di aerobica moderata (OMS). Creatina 3-5 g (informazione facoltativa)."},
  {"codice":"SAL-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"seduta saltata: un giorno pianificato di questa settimana, gia passato, non fatto, non riposo, non spostato. Scelte: seduta corta ora / 20 minuti a casa (secondo il \"piano B\" psicologico), sposta al prossimo giorno libero della settimana, slitta la settimana di un giorno (l'ultima seduta puo uscire), salta. Per chi ha senso di colpa o \"tutto o niente\": frase \"Un allenamento saltato non cancella i progressi\"."},
  {"codice":"ADE-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"aderenza: se negli ultimi 14 giorni le sedute fatte sono <70% delle previste (almeno 4 previste) e non lo ha gia chiesto negli ultimi 14 giorni: \"Cosa ti frena?\" Tempo -> toglie l'ultimo isolamento di ogni giorno con piu di 3 esercizi; Voglia -> un giorno in meno (riduciFrequenza) e invita a scegliere esercizi graditi; Dolori -> invita a segnalarlo a fine seduta."},
  {"codice":"ORA-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"orario abituale: se l'ora e passata di oltre 1 ora dall'orario scelto (e prima delle 23) e la seduta di oggi non e fatta: \"Di solito ti alleni alle HH:MM: oggi tocca a ...\"."},
  {"codice":"CIC-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"verdetto (verdettoCiclo): aderenza = sedute fatte / previste nel ciclo; quota = esercizi con e1RM in salita di oltre 2% / esercizi con >=2 misure. Esito: aderenza <70% -> 'aderenza'; quota >=50% -> 'buono'; altrimenti 'stallo'."},
  {"codice":"CIC-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"nuovo ciclo (nuovoCiclo): buono = stesso schema; stallo = alterna blocco ipertrofia/forza e cambia gli accessori (gli isolamenti diventano \"odiati temporanei\"); aderenza = un giorno in meno (o -15 minuti, min 30); livello aggiornato se stimato piu alto; avanzati con priorita: dopo 3 cicli di specializzazione uno bilanciato."},
  {"codice":"DOL-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"dopo un dolore moderato (fattore >=0,9) il giorno dopo il coach chiede \"stamattina e tornato come prima?\": si -> toglie il -10%; no -> il carico resta ridotto e segna il dato per l'esigenza del coach; consiglia il fisioterapista se continua a crescere."},
  {"codice":"BIA-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"BMI = peso / altezza^2; FFMI = massa magra / altezza^2."},
  {"codice":"BIA-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"massa grassa %: uomini atleta <=15, norma <=20, sopra la media <=25, oltre = \"elevata: meglio parlarne con un professionista\"; donne <=22 / <=30 / <=35 / oltre. Donne sotto il 17%: \"la funzione mestruale puo risentirne: da monitorare con un medico\"."},
  {"codice":"BIA-03","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"acqua corporea % del peso (nota informativa)."},
  {"codice":"ESI-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"parte al 120% senza bandiere dalla BIA, al 100% con una e al 95% con due (INT-02); a 120% piu volume dentro il range del livello e un RIR in meno su macchine e isolamenti; limiti 90-130%; si corregge ogni settimana (aggiornaEsigenza, si calcola il lunedi per la settimana precedente)."},
  {"codice":"ESI-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"variazioni settimanali: aderenza <70% (sedute fatte / giorni previsti): -10%; RPE medio sopra il bersaglio di almeno 1 (con >=3 serie con RPE): -5%; altrimenti prontezza media <50: -5%; altrimenti serie facili (RPE <= bersaglio-1, tutte le serie fatte, >=3 con RPE, nessun altro calo): +5%; dolore che non passa nella settimana: -10%."},
  {"codice":"ESI-03","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"esclusi (esigenza = 100%): modalita prudente (PAR-Q), over 65, \"momento di vita\" attivo che riduce volume o aumenta RIR."},
  {"codice":"INT-01","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"stato del corpo dalla BIA (`statoBia`): angolo di fase basso = sotto la media di eta e sesso di piu di 1,3 gradi (circa il 5 percentile, riferimenti a 50 kHz di Bosy-Westphal 2006, interpolati sopra i 50 anni) o sotto 5,04 uomini / 4,20 donne (soglia dove la funzione fisica peggiora, OR 3,07: molto basso); ECW/TBW da 0,40 in su = acqua extracellulare alta (normale 0,36-0,39; da 0,39 a 0,40 solo una nota sul modo di misurare). Livello di prudenza = numero di bandiere (angolo basso 1, molto basso 2, ECW alto 1; massimo 2). Valori fuori scala (angolo fuori 2-12, rapporto fuori 0,3-0,5) si ignorano. Le note spiegano numeri, limite e che non e una diagnosi, e consigliano di ripetere la BIA a digiuno e a riposo."},
  {"codice":"INT-02","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"esigenza di partenza (`esigenzaIniziale`): 120% senza bandiere, 100% con una, 95% con due. Si usa alla creazione del programma e quando il profilo non ha ancora un'esigenza. Non cambia per cauto, over 65 o periodi difficili (ESI-03)."},
  {"codice":"INT-03","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"con due bandiere (livello 2) una ripetizione in riserva in piu su tutti gli esercizi (`rirExtraIntensita`, usata da `rirBersaglio`). Motivo: le stime di RIR sbagliano gia di circa una ripetizione, per difetto (Halperin 2022; Refalo 2023)."},
  {"codice":"INT-04","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"prima volta con un esercizio (nessuna seduta in storico, spegnibile): una serie in meno (minimo 2) e una ripetizione in riserva in piu. Motivo: le prime sedute fanno piu indolenzimento (effetto della seduta ripetuta) e il carico di partenza e una stima (PAR-01..05). Il carico si corregge piu in fretta con CAR-16 e CAR-17."},
  {"codice":"INT-05","area":"Controlli periodici, corpo, costanza e fine ciclo","testo":"bilancio delle prime due sedute del programma (spegnibile, `bilancioPrimeSedute`, chiamato a fine seduta): con le prime due sedute registrate dall'inizio del programma, confronta serie fatte, sforzo (RPE rispetto al bersaglio) e prontezza. Meno del 75% delle serie fatte, o RPE medio di almeno 1 sopra il bersaglio, o prontezza sotto 50 (-5 invece di -10): esigenza -10 punti. Almeno il 95% delle serie fatte e RPE medio di almeno 1,5 sotto: +10 punti. Altrimenti resta. Limiti 90-130%. Si fa una volta per programma e il lunedi la correzione settimanale (ESI-02) non conta due volte lo sforzo e la prontezza della stessa settimana. Mostra un messaggio breve."},
  {"codice":"PSI-01","area":"Chi hai davanti: psicologia e momenti di vita","testo":"intensita: punteggio = preferenza (tranquilli 0, impegnativi 1, durissimi 2) + tolleranza (mi fermo 0, continuo 1, spingo 2); <=1 bassa, >=3 alta, altrimenti media (risposta mancante vale 1)."},
  {"codice":"PSI-02","area":"Chi hai davanti: psicologia e momenti di vita","testo":"fiducia bassa (\"poco\") -> principiante con >3 esercizi: -1 esercizio (PRG-03); primo mese con sedute un po' piu corte."},
  {"codice":"PSI-03","area":"Chi hai davanti: psicologia e momenti di vita","testo":"tutto-o-niente (\"spesso mollo\"): se salti, subito una seduta corta (SAL-01). Colpa (\"mi sento in colpa\" o motivazione \"dovere\"): messaggio \"niente sensi di colpa: contano le settimane\"."},
  {"codice":"PSI-04","area":"Chi hai davanti: psicologia e momenti di vita","testo":"disagio in palestra: -2 al bilanciere nella scelta degli esercizi (PRG-06), esercizi semplici con manubri e macchine, pochi cambi di postazione; \"osservato\": ogni esercizio ha la sua scheda tecnica."},
  {"codice":"PSI-05","area":"Chi hai davanti: psicologia e momenti di vita","testo":"varieta: \"sempre gli stessi\" = fattore 0 (nessuna variazione casuale), \"un po' di tutto\" = 1, \"cambiare spesso\" = 1,6 (moltiplica la variazione di PRG-06)."},
  {"codice":"PSI-06","area":"Chi hai davanti: psicologia e momenti di vita","testo":"intensita bassa: niente drop/AMRAP/back-off (PRG-34), +1 ripetizione in riserva (limite 4-5), -1 serie sull'ultimo esercizio (PRG-36); intensita alta: tecniche intense ammesse, il cedimento resta sugli isolamenti."},
  {"codice":"PSI-07","area":"Chi hai davanti: psicologia e momenti di vita","testo":"motivazione: piacere -> sfide e record; valore -> ogni scelta col suo perche; altri -> piccoli traguardi visibili."},
  {"codice":"PSI-08","area":"Chi hai davanti: psicologia e momenti di vita","testo":"piano B: corta (20 minuti, primi 3 esercizi x 2 serie), casa (20 minuti a corpo libero: squat, piegamenti, ponte glutei, affondi inversi, plank x 2 serie), sposta (primo giorno libero)."},
  {"codice":"PSI-09","area":"Chi hai davanti: psicologia e momenti di vita","testo":"ritratto (ritrattoCoach): fino a 4 righe nel programma che dicono quali regole sono cambiate per te."},
  {"codice":"PSI-10","area":"Chi hai davanti: psicologia e momenti di vita","testo":"\"primi passi\" (htmlPrimiPassi): per fiducia bassa, tutto-o-niente, motivazione \"altri\" o principianti, nei primi 28 giorni del programma: contatore x/8 allenamenti, \"Obiettivo: 2 sedute a settimana\" (studio 2026 su 389 mila utenti)."},
  {"codice":"MOM-01","area":"Chi hai davanti: psicologia e momenti di vita","testo":"attivare un periodo: le serie di tutti gli esercizi del piano x fattore volume (min 1); si tolgono le tecniche se \"niente tecniche\"; si salva una copia (nome, serie, tecnica) per tornare indietro; fine prevista = oggi + settimane."},
  {"codice":"MOM-02","area":"Chi hai davanti: psicologia e momenti di vita","testo":"effetti: RIR bersaglio +RIR del periodo (rirBersaglio); esigenza del coach = 100% (ESI-03); volume del programma (PRG-27)."},
  {"codice":"MOM-03","area":"Chi hai davanti: psicologia e momenti di vita","testo":"chiusura: alla fine del periodo \"Come va?\" -> \"Sto meglio\" (ripristina le serie dalla copia) o \"Ancora due settimane\". Un periodo attivo non si chiude per sbaglio: dalle Opzioni serve una conferma. Ogni 7 giorni \"verifica\"."},
  {"codice":"MOM-04","area":"Chi hai davanti: psicologia e momenti di vita","testo":"salvaguardia (\"guardia\"): se in 7 giorni ci sono piu allenamenti dei previsti +1: \"Anche il riposo fa crescere. Se allenarti diventa un obbligo o ti fa stare in ansia quando salti, parlane con qualcuno.\""},
  {"codice":"MOM-05","area":"Chi hai davanti: psicologia e momenti di vita","testo":"aiuto (\"aiuto\"): messaggio \"Se il malessere non passa o diventa pesante, parlane con il medico o con uno psicologo\"."},
  {"codice":"MOM-06","area":"Chi hai davanti: psicologia e momenti di vita","testo":"settimana pesante: se la prontezza media degli ultimi 8 giorni (>=3 misure) e <50, il coach chiede \"Cosa succede?\" e propone di segnare un periodo (Hooper: >7 giorni = segnale)."},
  {"codice":"RIC-01","area":"Regole aggiunte dalla ricerca (RIC)","testo":"serie in più nelle settimane centrali del blocco (Pelland 2025, Bell 2024): in una settimana di carico che non è né la prima né l'ultima prima dello scarico, +1 serie (massimo 5) sugli esercizi dei muscoli prioritari, se la prontezza media delle ultime due sedute registrate è almeno 70 (o non c'è alcun dato). Con lo scarico si torna alle serie del programma."},
  {"codice":"RIC-02","area":"Regole aggiunte dalla ricerca (RIC)","testo":"pausa prima di abbassare il carico (Singer 2024): se nell'ultima seduta tutte le serie tranne l'ultima erano complete (almeno 3 serie) e il carico resta fermo, +45 secondi di pausa. Prima lo faceva solo il principiante (+30)."},
  {"codice":"RIC-03","area":"Regole aggiunte dalla ricerca (RIC)","testo":"posizione allungata per petto, schiena e glutei (Maeo 2021-2023, Pedrosa 2025): croci su panca coi manubri, pullover coi manubri, affondi bulgari e stacco rumeno contano come esercizi in allungamento (preferiti nella scelta); «Croci ai Cavi» e «Pullover ai Cavi» si scambiano con le varianti coi manubri se l'attrezzo c'è."},
  {"codice":"RIC-04","area":"Regole aggiunte dalla ricerca (RIC)","testo":"tetto alle tecniche al cedimento (Robinson 2024): al massimo una tecnica intensa (drop set, AMRAP, parziali, calibrazione) per seduta; nessuna nella settimana di scarico o con prontezza sotto 50. La tecnica del programma resta: per quel giorno non compare."},
  {"codice":"RIC-05","area":"Regole aggiunte dalla ricerca (RIC)","testo":"rientro per tutto il piano (detraining, SBS): se dall'ultima seduta sono passati almeno 14 giorni (7 sopra i 65 anni), la prima seduta ha il 25% di serie in meno su ogni esercizio (minimo 2) in aggiunta al calo di carico per esercizio di CAR (rientro dopo una pausa). Il carico per esercizio c'era già: la novità è il volume."}
];
window.regolaDescritta = function(codice) { return COACH_REGOLE.find(r => r.codice === codice) || null; };
